mapper.select:
select id,
msg_title,
msg_content,
send_time,
view_status,
msg_type,
relate_link
from user_msg

    target_user = #{vo.userId}

        and msg_title like concat('%', #{vo.keyword}, '%')


        and msg_type = #{vo.msgType}


        and view_status = #{vo.viewStatus}


        and send_time >= #{vo.sendTimeStart}


        and #{vo.sendTimeEnd} >= send_time


        and src_app = #{vo.srcApp}


order by send_time desc

select msg.id, msg.src_id, msg.src_app, msg.msg_title, msg.msg_content, msg.target_user, msg.send_time, msg.view_status, msg.msg_type, msg.relate_link, msg.origin_json from user_msg msg join user_org uo on msg.target_user = uo.user_id
uo.org_id in
#{orgId}
and msg.view_status = #{vo.viewStatus}
and (msg.msg_title like concat('%', #{vo.keyword}, '%') or msg.msg_content like concat('%', #{vo.keyword}, '%'))
and msg.msg_type = #{vo.msgType}
and msg.src_app in
#{a}
and msg.src_app = #{vo.srcApp}
and msg.tenant_id = #{vo.tenantId}
and msg.send_time >= #{vo.sendTimeStart}
and #{vo.sendTimeEnd} >= msg.send_time
order by msg.send_time desc

select msg.id, msg.src_id, msg.src_app, msg.msg_title, msg.msg_content, msg.target_user, msg.send_time, msg.view_status, msg.msg_type, msg.relate_link, msg.origin_json from user_msg msg join user_org uo on msg.target_user = uo.user_id where msg.id = #{id} and uo.org_id in
#{orgId}
limit 1

select distinct msg.src_app from user_msg msg join user_org uo on msg.target_user = uo.user_id where uo.org_id in
#{orgId}
and msg.src_app is not null and msg.src_app != '' order by msg.src_app
